const $=s=>document.querySelector(s), esc=s=>String(s??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const links=[['dashboard','Overview','dashboard.html'],['astronauts','Crew profiles','astronauts.html'],['missions','Missions','missions.html'],['readings','Health monitoring','readings.html'],['baselines','Personal baselines','baselines.html'],['analytics','Analytics','analytics.html'],['alerts','Alerts','alerts.html'],['medical','Medical review','medical-review.html'],['notifications','Notifications','notifications.html'],['reports','Reports','reports.html'],['history','Health history','history.html'],['settings','Settings & access','settings.html']];
const labels={dashboard:['Mission overview','A clear view of crew health, mission context, and review activity.'],astronauts:['Astronaut profiles','Synthetic crew profiles, assignments, and health history.'],missions:['Mission management','Create missions and track status, phase, and crew.'],readings:['Health monitoring','Record and review contextual health measurements.'],baselines:['Personal baselines','Activity-specific Earth references, reviewed before use.'],analytics:['Research analytics','Explore real stored readings by environment, activity, and quality.'],alerts:['Alert management','Review illustrative statistical changes with their full context.'],medical:['Medical review','Pending baseline decisions and open alert reviews.'],notifications:['Notifications','Account-specific review and mission updates.'],reports:['Reports','Print a clearly labelled synthetic-data report or export readings.'],history:['Health history','Readings, comparisons, alerts, and preserved baseline versions.'],settings:['Settings & access','Account details, access roles, and audit activity.']};
async function api(path,opts={}){let r;try{r=await fetch('/api'+path,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(opts.headers||{})},...opts})}catch(e){if(opts.method==='POST'&&path==='/readings')return queueReading(JSON.parse(opts.body));if(!opts.method||opts.method==='GET'){let cached=await getApiCache(path).catch(()=>null);if(cached!==null)return cached}throw Error('The local server is unavailable. Reconnect to refresh live records.')}let d;try{d=await r.json()}catch{d={}}if(r.status===401&&document.body.dataset.page!=='login'){location.href='/login.html';throw Error('Please sign in to continue.')}if(!r.ok)throw Error(d.detail||'The request could not be completed.');if((!opts.method||opts.method==='GET')&&!path.startsWith('/auth/login'))await putApiCache(path,d).catch(()=>{});return d}
function toast(s){let t=document.createElement('div');t.className='toast';t.textContent=s;document.body.append(t);setTimeout(()=>t.remove(),3200)}
function openQueue(){return new Promise((resolve,reject)=>{const req=indexedDB.open('astra-local-queue-v1',2);req.onupgradeneeded=()=>{let d=req.result;if(!d.objectStoreNames.contains('readings'))d.createObjectStore('readings',{keyPath:'client_request_id'});if(!d.objectStoreNames.contains('api-cache'))d.createObjectStore('api-cache',{keyPath:'path'})};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function putApiCache(path,data){if(path.startsWith('/auth/')||path.startsWith('/users')||path.startsWith('/audit-logs')||path.startsWith('/notifications'))return;const db=await openQueue();return new Promise((ok,no)=>{let tx=db.transaction('api-cache','readwrite');tx.objectStore('api-cache').put({path,data,cached_at:new Date().toISOString()});tx.oncomplete=ok;tx.onerror=()=>no(tx.error)})}
async function getApiCache(path){const db=await openQueue();return new Promise((ok,no)=>{const r=db.transaction('api-cache').objectStore('api-cache').get(path);r.onsuccess=()=>ok(r.result?.data??null);r.onerror=()=>no(r.error)})}
async function queueReading(record){const db=await openQueue(),id=crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random().toString(16).slice(2)}`;const owner=JSON.parse(sessionStorage.getItem('astra-user-profile')||'{}').email||'';const item={...record,client_request_id:id,owner_email:owner,queued_at:new Date().toISOString()};await new Promise((ok,no)=>{const tx=db.transaction('readings','readwrite');tx.objectStore('readings').put(item);tx.oncomplete=ok;tx.onerror=()=>no(tx.error)});return {local_pending:true,sync_status:'waiting_to_sync',reading:item}}
async function getQueued(){const db=await openQueue();return new Promise((ok,no)=>{const r=db.transaction('readings').objectStore('readings').getAll();r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error)})}
async function clearQueued(id){const db=await openQueue();return new Promise(ok=>{const tx=db.transaction('readings','readwrite');tx.objectStore('readings').delete(id);tx.oncomplete=ok;tx.onerror=ok})}
async function clearLocalCache(){const db=await openQueue();return new Promise(ok=>{const tx=db.transaction('api-cache','readwrite');tx.objectStore('api-cache').clear();tx.oncomplete=ok;tx.onerror=ok})}
async function syncPending(){if(!navigator.onLine)return;let records;try{records=await getQueued()}catch{return}for(const item of records){try{const r=await fetch('/api/readings',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(item)});if(r.ok)await clearQueued(item.client_request_id);else if(r.status===401){location.href='/login.html';return}}catch{return}}}
const date=x=>x?new Date(x).toLocaleString():'';
function shell(page){let title=labels[page][0];$('#app').innerHTML=`<div class="app-shell"><aside class="sidebar"><a class="brand" href="/"><span class="mark">✦</span> ASTRA <b>HEALTH</b></a><div class="side-label">MISSION CONTROL</div><nav class="nav-links">${links.map(([id,n,u])=>`<a class="${id===page?'active':''}" href="/${u}">${n}</a>`).join('')}</nav><div class="side-bottom">Educational decision-support prototype.<br>Not a diagnostic system.<br><a href="/">← Product overview</a></div></aside><section class="main"><header class="app-header"><span class="crumb">ASTRA HEALTH / ${esc(title.toUpperCase())}</span><div class="header-tools"><span class="connection" id="connection">Checking local server</span><a class="notify-pill" href="/notifications.html">Updates <span id="notice-count">–</span></a><span id="identity" class="user-chip">Loading account…</span><button class="secondary small" data-action="logout">Sign out</button></div></header><main class="content"><div class="page-title"><div><h1>${esc(title)}</h1><p>${esc(labels[page][1])}</p></div><span class="offline-note">Synthetic demo records · <span id="network">Checking connection…</span></span></div><div id="view"><div class="spinner"></div></div></main></section></div>`;updateNetwork();window.addEventListener('online',()=>{updateNetwork();syncPending()});window.addEventListener('offline',updateNetwork)}
function updateNetwork(){let online=navigator.onLine;let c=$('#connection'),n=$('#network');if(c)c.textContent=online?'Local server connected':'Offline · cached application';if(n)n.textContent=online?'Online':'Offline · new readings queue on this device'}
function card(title,sub,body,extra=''){return `<section class="card ${extra}"><div class="card-head"><div><h2>${title}</h2>${sub?`<div class="card-sub">${sub}</div>`:''}</div></div>${body}</section>`}
function badge(t){let cl=/APPROVED|VALID|ACTIVE|RESOLVED/.test(t)?'ok':/PENDING|REVIEW|QUESTIONABLE|OPEN/.test(t)?'warn':/INVALID|REJECTED|HIGH/.test(t)?'bad':'';return `<span class="badge ${cl}">${esc(t)}</span>`}
function table(headers,rows,empty='No records yet.'){return `<div class="table-wrap"><table class="data-table"><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${headers.length}" class="empty"><strong>${empty}</strong>Load the demo or create a record to get started.</td></tr>`}</tbody></table></div>`}
function chart(values,color='') {let vals=values.filter(x=>x!=null).slice(-12);if(vals.length<2)return `<div class="empty"><strong>Not enough readings yet</strong>Load demo data to see this trend.</div>`;let min=Math.min(...vals),max=Math.max(...vals),span=max-min||1,pts=vals.map((v,i)=>`${20+i*360/(vals.length-1)},${165-(v-min)/span*125}`).join(' ');return `<div class="chart"><svg viewBox="0 0 400 205" preserveAspectRatio="none"><defs><linearGradient id="fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#2877ef" stop-opacity=".19"/><stop offset="1" stop-color="#2877ef" stop-opacity="0"/></linearGradient></defs>${[40,80,120,160].map(y=>`<line class="gridline" x1="15" y1="${y}" x2="390" y2="${y}"/>`).join('')}<polygon class="area" points="${pts} 380,175 20,175"/><polyline class="line ${color}" points="${pts}"/>${vals.map((v,i)=>`<circle cx="${20+i*360/(vals.length-1)}" cy="${165-(v-min)/span*125}" r="3.5" fill="#2877ef"/>`).join('')}<text x="18" y="197">Older</text><text x="350" y="197">Recent</text><text x="330" y="25">${esc(Math.round(max))}</text><text x="330" y="169">${esc(Math.round(min))}</text></svg></div>`}
function readingRows(xs){return xs.map(r=>`<tr><td>${esc(r.astronaut_name||'Crew '+r.astronaut_id)}</td><td>${date(r.timestamp)}</td><td>${esc(r.environment)}</td><td>${esc(r.activity)}</td><td>${r.heart_rate??'—'}</td><td>${r.spo2??'—'}${r.spo2?'%':''}</td><td>${badge(r.sensor_quality)}</td></tr>`)}
async function dashboardCore(){let d=await api('/dashboard'),stats=[['Astronauts',d.astronauts,'Crew profiles'],['Active missions',d.active_missions,'In progress'],['Health readings',d.readings,'Stored records'],['Approved baselines',d.approved_baselines,'Available for comparison'],['Pending reviews',d.pending_reviews,'Baseline decisions'],['Active alerts',d.active_alerts,'Awaiting review']];let vals=d.recent_readings.slice().reverse();$('#view').innerHTML=`<div class="toolbar" style="margin-bottom:16px"><button data-action="setup">Load demo data</button><button class="secondary" data-action="generate">Generate baseline</button><button class="secondary" data-action="simulate">Simulate space reading</button><button class="danger" data-action="reset">Reset demo data</button></div><div class="grid stats">${stats.map(([a,b,c])=>`<section class="card"><div class="stat-label">${a}</div><div class="stat-value">${b}</div><div class="stat-foot">${c}</div></section>`).join('')}</div><div class="grid dash-grid">${card('Heart rate trend','Recent saved readings · BPM',chart(vals.map(x=>x.heart_rate)))}${card('Recent alerts','Illustrative decision-support flags',`<div class="list">${d.alerts.length?d.alerts.map(a=>`<div class="list-item"><div><div class="item-main">${esc(a.astronaut_name)}</div><div class="item-meta">${esc(a.explanation)}</div></div>${badge(a.severity)}</div>`).join(''):'<div class="empty"><strong>No active alerts</strong>Assessment flags will appear here when illustrative rules are met.</div>'}</div>`)}</div><div class="grid dash-grid">${card('SpO₂ trend','Recent saved readings · %',chart(vals.map(x=>x.spo2),'cyan'))}${card('Blood pressure · systolic','Recent saved readings · mmHg',chart(vals.map(x=>x.systolic),'orange'))}</div><div class="grid section-grid">${card('Recent readings','Latest saved records',table(['Astronaut','Timestamp','Environment','Activity','Heart rate','SpO₂','Quality'],readingRows(d.recent_readings.slice(0,8))))}${card('Data quality','All stored readings',`<div class="metric-list">${Object.entries(d.quality).map(([k,v])=>`<div class="metric"><strong>${v}</strong><small>${k} sensor readings</small></div>`).join('')}</div><div class="notice">${esc(d.sync_status)}. Frontend shell can be cached; API records require the local server.</div>`)}</div>`}
async function astronauts(){let xs=await api('/astronauts'),ms=await api('/missions');$('#view').innerHTML=`<section class="card form-card"><div class="card-head"><div><h2>Add astronaut</h2><div class="card-sub">Use synthetic information for demonstration.</div></div></div><form id="astronaut-form"><div class="form-grid"><div class="field"><label>Name</label><input name="name" required minlength="2" placeholder="e.g. Avery Morgan"></div><div class="field"><label>Call sign</label><input name="call_sign" required placeholder="e.g. AURORA-02"></div><div class="field"><label>Role</label><input name="role" value="Crew member"></div><div class="field"><label>Mission</label><select name="mission_id"><option value="">Unassigned</option>${ms.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div></div><div class="form-actions"><button>Add astronaut</button></div></form></section>${card('Crew profiles','Current prototype records',table(['Name','Call sign','Role','Mission','Readings','Baseline status','Action'],xs.map(x=>`<tr><td><strong>${esc(x.name)}</strong></td><td>${esc(x.call_sign)}</td><td>${esc(x.role)}</td><td>${esc(x.mission_name||'Unassigned')}</td><td>${x.reading_count}</td><td>${badge('See baselines')}</td><td><a class="text-link" href="/history.html?astronaut_id=${x.id}">History</a> <button class="secondary small" data-action="edit-astronaut" data-id="${x.id}">Edit</button></td></tr>`)))}`}
async function missions(){let xs=await api('/missions');$('#view').innerHTML=`<section class="card form-card"><div class="card-head"><div><h2>Create mission</h2><div class="card-sub">Mission phases provide context for each record.</div></div></div><form id="mission-form"><div class="form-grid"><div class="field"><label>Name</label><input name="name" required minlength="2"></div><div class="field"><label>Status</label><select name="status"><option>PLANNED</option><option>ACTIVE</option><option>COMPLETED</option></select></div><div class="field"><label>Phase</label><select name="phase">${['EARTH_PREPARATION','LAUNCH','ORBIT','SPACE_OPERATION','RETURN','POST_MISSION'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Start date</label><input name="start_date" type="date"></div><div class="field"><label>End date</label><input name="end_date" type="date"></div><div class="field"><label>Description</label><input name="description"></div></div><div class="form-actions"><button>Create mission</button></div></form></section>${card('Missions','Mission assignments and phases',table(['Mission','Status','Phase','Start','End','Description','Action'],xs.map(x=>`<tr><td><strong>${esc(x.name)}</strong></td><td>${badge(x.status)}</td><td>${esc(x.phase)}</td><td>${esc(x.start_date||'—')}</td><td>${esc(x.end_date||'—')}</td><td>${esc(x.description||'—')}</td><td><button class="secondary small" data-action="edit-mission" data-id="${x.id}">Edit</button></td></tr>`)))}`}
async function readings(){let [xs,people]=await Promise.all([api('/readings'),api('/astronauts')]);$('#view').innerHTML=`<section class="card form-card"><div class="card-head"><div><h2>Enter a simulated reading</h2><div class="card-sub">Blank vital fields stay missing; they are never treated as zero.</div></div></div><form id="reading-form"><div class="form-grid"><div class="field"><label>Astronaut</label><select name="astronaut_id" required>${people.map(x=>`<option value="${x.id}">${esc(x.name)} · ${esc(x.call_sign)}</option>`).join('')}</select></div><div class="field"><label>Activity</label><select name="activity">${['RESTING','SLEEPING','WALKING','EXERCISE','WORKING','OTHER'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Environment</label><select name="environment"><option>EARTH</option><option>SPACE</option></select></div><div class="field"><label>Mission phase</label><select name="phase">${['EARTH_PREPARATION','LAUNCH','ORBIT','SPACE_OPERATION','RETURN','POST_MISSION'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Heart rate (BPM)</label><input name="heart_rate" type="number" min="20" max="240"></div><div class="field"><label>SpO₂ (%)</label><input name="spo2" type="number" min="50" max="100"></div><div class="field"><label>Systolic BP</label><input name="systolic" type="number" min="50" max="260"></div><div class="field"><label>Diastolic BP</label><input name="diastolic" type="number" min="30" max="180"></div><div class="field"><label>Sensor quality</label><select name="sensor_quality"><option>VALID</option><option>QUESTIONABLE</option><option>INVALID</option></select></div><div class="field"><label>Sensor source</label><input name="sensor_source" value="Manual entry"></div></div><div class="form-actions"><button>Save reading</button></div></form></section><div class="toolbar" style="margin-bottom:12px"><select id="filter-activity"><option value="">All activities</option>${['RESTING','SLEEPING','WALKING','EXERCISE','WORKING','OTHER'].map(x=>`<option>${x}</option>`).join('')}</select><select id="filter-env"><option value="">All environments</option><option>EARTH</option><option>SPACE</option></select><button class="secondary" data-action="filter">Filter</button></div><div id="reading-table">${card('Health readings','Latest saved measurements',table(['Astronaut','Timestamp','Environment','Activity','Heart rate','SpO₂','Quality'],readingRows(xs)))}</div>`}
async function baselines(){let [xs,people]=await Promise.all([api('/baselines'),api('/astronauts')]);$('#view').innerHTML=`<section class="card form-card"><div class="card-head"><div><h2>Generate baseline</h2><div class="card-sub">Requires at least five VALID Earth readings for the selected astronaut and activity. A new baseline starts pending review.</div></div></div><form id="baseline-form"><div class="form-grid"><div class="field"><label>Astronaut</label><select name="astronaut_id" required>${people.map(x=>`<option value="${x.id}">${esc(x.name)} · ${esc(x.call_sign)}</option>`).join('')}</select></div><div class="field"><label>Activity</label><select name="activity">${['RESTING','SLEEPING','WALKING','EXERCISE','WORKING','OTHER'].map(x=>`<option>${x}</option>`).join('')}</select></div></div><div class="form-actions"><button>Calculate baseline</button></div></form><div class="notice warn">Only VALID Earth readings count. Approval is a simulated reviewer action and does not represent clinical review.</div></section><div class="grid">${xs.length?xs.map(x=>card(`${esc(x.astronaut_name)} · ${esc(x.activity)} · v${x.version}`,`Created ${date(x.created_at)} · ${x.sample_count} valid readings · ${badge(x.status)}`,`<div class="metric-list">${Object.entries(x.statistics||{}).map(([k,v])=>`<div class="metric"><strong>${esc(k.replace('_',' '))}</strong><small>Mean ${v.mean.toFixed(2)} · median ${v.median.toFixed(2)} · SD ${v.std_dev.toFixed(2)}<br>Range ${v.min}–${v.max} · n=${v.count}</small></div>`).join('')}</div>${x.status==='PENDING'?`<div class="form-actions"><button data-action="approve" data-id="${x.id}">Approve (simulated reviewer)</button><button class="danger" data-action="reject" data-id="${x.id}">Reject</button></div>`:`<div class="notice">${x.review?`Decision by ${esc(x.review.reviewer)} · ${date(x.review.reviewed_at)} · ${esc(x.review.comments||'No comments')}`:'Historical version preserved.'}</div>`}`)).join(''):`<section class="card empty"><strong>No baselines yet</strong>Load the demo, then calculate the five-sample Earth baseline.</section>`}</div>`}
async function alerts(){let xs=await api('/alerts');$('#view').innerHTML=`<div class="notice warn">These are configurable illustrative statistical flags. They are not clinical emergency levels and do not diagnose a condition.</div>${card('Alert history','Assessment explanation and review status',table(['ID','Astronaut','Timestamp','Activity','Observed vs mean','Sensor quality','Severity','Explanation','Review'],xs.map(a=>{let r=a.reading||{},mets=a.assessment.metrics||[];return `<tr><td>#${a.id}</td><td>${esc(a.astronaut_name)}</td><td>${date(a.created_at)}</td><td>${esc(r.activity||'—')}</td><td>${mets.map(m=>`${esc(m.parameter)}: ${m.observed} / ${m.mean.toFixed(1)}`).join('<br>')||'—'}</td><td>${badge(r.sensor_quality||'—')}</td><td>${badge(a.severity)}</td><td>${esc(a.explanation)}</td><td>${a.status==='OPEN'?`<button class="secondary small" data-action="ack" data-id="${a.id}">Acknowledge</button>`:`${badge(a.status)}<br><small>${esc(a.comments||'')}</small>`}</td></tr>`})))}`}
async function history(){let [xs,bs,assessments]=await Promise.all([api('/history'),api('/baselines'),api('/assessments')]),aid=new URLSearchParams(location.search).get('astronaut_id');if(aid)xs=xs.filter(x=>x.astronaut_id==aid);$('#view').innerHTML=`<div class="toolbar" style="margin-bottom:15px"><a class="button secondary" href="/api/reports/readings.csv">Export readings CSV</a><span class="offline-note">CSV contains synthetic measurement history.</span></div>${card('Health reading history',`${xs.length} records`,table(['Astronaut','Timestamp','Environment','Activity','Heart rate','SpO₂','Systolic','Diastolic','Sensor quality','Phase'],xs.map(r=>`<tr><td>${esc(r.astronaut_name)}</td><td>${date(r.timestamp)}</td><td>${esc(r.environment)}</td><td>${esc(r.activity)}</td><td>${r.heart_rate??'—'}</td><td>${r.spo2??'—'}</td><td>${r.systolic??'—'}</td><td>${r.diastolic??'—'}</td><td>${badge(r.sensor_quality)}</td><td>${esc(r.phase)}</td></tr>`)))}<div class="grid section-grid" style="margin-top:16px">${card('Assessment history','Captured comparison decisions',table(['ID','Reading','Baseline','Created','Result'],assessments.map(a=>`<tr><td>#${a.id}</td><td>#${a.reading_id}</td><td>${a.baseline_id??'Unavailable'}</td><td>${date(a.created_at)}</td><td>${esc(a.result.message)}</td></tr>`)))}${card('Baseline versions','Full preserved baseline history',table(['Astronaut','Activity','Version','Created','Valid samples','Status'],bs.map(b=>`<tr><td>${esc(b.astronaut_name)}</td><td>${esc(b.activity)}</td><td>v${b.version}</td><td>${date(b.created_at)}</td><td>${b.sample_count}</td><td>${badge(b.status)}</td></tr>`)))}</div>`}
async function loginPage(){let s=await api('/auth/setup-status').catch(()=>({needs_admin:true}));$('#app').innerHTML=`<main class="login-layout"><section class="login-brand"><a class="brand" href="/"><span class="mark">✦</span> ASTRA <b>HEALTH</b></a><p class="eyebrow">CREW HEALTH INTELLIGENCE</p><h1>Personal context.<br>Clearer review.</h1><p>Sign in to the local ASTRA HEALTH research prototype. This educational build uses synthetic data.</p><a class="text-link" href="/">← Return to product overview</a></section><section class="login-panel"><div class="login-card"><div class="eyebrow">SECURE LOCAL ACCESS</div><h2>${s.needs_admin?'Set up your administrator':'Welcome back'}</h2><p>${s.needs_admin?'Create the first administrator. This step is available only once on this database.':'Sign in with an account configured by the administrator.'}</p><form id="login-form" class="login-form">${s.needs_admin?`<div class="field"><label>Full name</label><input name="full_name" required minlength="2" autocomplete="name"></div>`:''}<div class="field"><label>Email address</label><input name="email" type="email" required autocomplete="username"></div><div class="field"><label>Password</label><input name="password" type="password" required minlength="${s.needs_admin?12:1}" autocomplete="${s.needs_admin?'new-password':'current-password'}">${s.needs_admin?'<small>Use at least 12 characters. The password is stored as a salted hash.</small>':''}</div><button class="full">${s.needs_admin?'Create administrator':'Sign in'} <span>→</span></button></form><div id="login-error" class="form-error" hidden></div><div class="notice">Health records are synthetic in this classroom prototype. Session cookies are HttpOnly and expire automatically.</div></div></section></main>`;$('#login-form').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.currentTarget));try{if(s.needs_admin)await api('/auth/bootstrap',{method:'POST',body:JSON.stringify(d)});else await api('/auth/login',{method:'POST',body:JSON.stringify({email:d.email,password:d.password})});location.href='/dashboard.html'}catch(err){let x=$('#login-error');x.hidden=false;x.textContent=err.message}}}
async function analytics(){let [d,people]=await Promise.all([api('/analytics'),api('/astronauts')]);$('#view').innerHTML=`<div class="grid stats stats-4"><section class="card"><div class="stat-label">Stored readings</div><div class="stat-value">${d.total}</div><div class="stat-foot">From the local database</div></section><section class="card"><div class="stat-label">Earth records</div><div class="stat-value">${d.by_environment.EARTH}</div><div class="stat-foot">Pre-mission reference data</div></section><section class="card"><div class="stat-label">Space records</div><div class="stat-value">${d.by_environment.SPACE}</div><div class="stat-foot">In-mission observations</div></section><section class="card"><div class="stat-label">Activity types</div><div class="stat-value">${Object.keys(d.by_activity).length}</div><div class="stat-foot">Context groups represented</div></section></div><div class="grid dash-grid">${card('Heart rate over time','Actual saved records · BPM',chart(d.series.map(x=>x.heart_rate)))}${card('Oxygen saturation over time','Actual saved records · %',chart(d.series.map(x=>x.spo2),'cyan'))}</div><div class="grid section-grid">${card('Readings by activity','Counts from stored records',`<div class="metric-list">${Object.entries(d.by_activity).map(([k,v])=>`<div class="metric"><strong>${esc(k.replaceAll('_',' '))}</strong><small>${v} readings</small></div>`).join('')||'<p>No readings available.</p>'}</div>`)}${card('Sensor quality','Quality labels stored with readings',`<div class="metric-list">${Object.entries(d.quality).map(([k,v])=>`<div class="metric"><strong>${v}</strong><small>${esc(k)} readings</small></div>`).join('')}</div><div class="notice">Charts describe the stored synthetic dataset. They are research summaries, not clinical findings.</div>`)}</div>`}
async function medical(){let [bs,as]=await Promise.all([api('/baselines'),api('/alerts')]);let pending=bs.filter(x=>x.status==='PENDING'),open=as.filter(x=>x.status==='OPEN');$('#view').innerHTML=`<div class="notice warn">Medical Officer and Administrator role credentials are required for approval and alert review. A role in this student prototype does not verify clinical qualifications.</div><div class="grid section-grid">${card('Pending baseline approvals',`${pending.length} awaiting a decision`,table(['Astronaut','Activity','Version','Samples','Created','Action'],pending.map(b=>`<tr><td>${esc(b.astronaut_name)}</td><td>${esc(b.activity)}</td><td>v${b.version}</td><td>${b.sample_count}</td><td>${date(b.created_at)}</td><td><button class="small" data-action="approve" data-id="${b.id}">Approve</button> <button class="danger small" data-action="reject" data-id="${b.id}">Reject</button></td></tr>`,'No baseline reviews are waiting.')))}${card('Open alerts',`${open.length} awaiting acknowledgement`,table(['Astronaut','Severity','Reason','Raised','Action'],open.map(a=>`<tr><td>${esc(a.astronaut_name)}</td><td>${badge(a.severity)}</td><td>${esc(a.explanation)}</td><td>${date(a.created_at)}</td><td><button class="secondary small" data-action="ack" data-id="${a.id}">Acknowledge</button></td></tr>`,'No alerts need review.')))}</div>`}
async function reports(){let [people,rows,bs,as]=await Promise.all([api('/astronauts'),api('/history'),api('/baselines'),api('/alerts')]);$('#view').innerHTML=`<div class="toolbar no-print" style="margin-bottom:15px"><label for="report-person">Crew profile</label><select id="report-person"><option value="">All synthetic records</option>${people.map(x=>`<option value="${x.id}">${esc(x.name)} · ${esc(x.call_sign)}</option>`)}</select><button data-action="report-filter" class="secondary">Preview report</button><button data-action="print-report">Print / Save as PDF</button><a class="button secondary" href="/api/reports/readings.csv">Download CSV</a></div><div id="report-preview">${card('ASTRA HEALTH · RESEARCH SUMMARY','Generated from database records',`<div class="notice">Educational prototype · Synthetic information only · Not for clinical use.</div><p>${rows.length} readings · ${bs.length} baseline versions · ${as.length} alerts</p>${table(['Astronaut','Timestamp','Environment','Activity','Heart rate','SpO₂','Quality'],readingRows(rows.slice(0,20)))}`)}</div>`}
async function settings(){let me=await api('/auth/me');$('#view').innerHTML=`<div class="grid section-grid"><section class="card"><div class="card-head"><div><h2>Signed-in account</h2><div class="card-sub">Local session is held in a short-lived HttpOnly cookie.</div></div></div><div class="metric-list"><div class="metric"><strong>${esc(me.full_name)}</strong><small>${esc(me.email)}</small></div><div class="metric"><strong>${badge(me.role)}</strong><small>Access role</small></div></div><div class="notice">A configured role controls restricted actions. It does not verify real-world professional credentials.</div></section><section class="card" id="user-admin"><div class="card-head"><div><h2>Account management</h2><div class="card-sub">Administrator role required.</div></div></div><div id="user-list"><div class="spinner"></div></div></section></div><div class="card" style="margin-top:16px" id="audit-card"><div class="card-head"><div><h2>Audit activity</h2><div class="card-sub">Recent sign-in and review actions.</div></div></div><div id="audit-list">Loading access log…</div></div>`;try{let users=await api('/users');$('#user-list').innerHTML=`<form id="user-form"><div class="form-grid"><div class="field"><label>Full name</label><input name="full_name" required></div><div class="field"><label>Email</label><input name="email" type="email" required></div><div class="field"><label>Role</label><select name="role">${['MEDICAL_OFFICER','RESEARCHER','ASTRONAUT','ADMINISTRATOR'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Initial password (12+ characters)</label><input name="password" type="password" minlength="12" required></div></div><div class="form-actions"><button>Add account</button></div></form>${table(['Name','Email','Role','Status'],users.map(u=>`<tr><td>${esc(u.full_name)}</td><td>${esc(u.email)}</td><td>${badge(u.role)}</td><td>${badge(u.active?'ACTIVE':'INACTIVE')}</td></tr>`))}`;$('#user-form').onsubmit=async e=>{e.preventDefault();await api('/users',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});toast('Account created');await settings()};let logs=await api('/audit-logs');$('#audit-list').innerHTML=table(['When','User','Action','Record','Details'],logs.map(x=>`<tr><td>${date(x.created_at)}</td><td>${esc(x.user_name)}</td><td>${esc(x.action)}</td><td>${esc(x.entity)} ${esc(x.entity_id||'')}</td><td>${esc(x.detail)}</td></tr>`))}catch(e){$('#user-list').innerHTML=`<div class="notice">${esc(e.message)} User administration is available to the Administrator role.</div>`;$('#audit-list').textContent='Audit log access is restricted to administrators.'}}
async function readings(){let [xs,people,pending]=await Promise.all([api('/readings'),api('/astronauts'),getQueued().catch(()=>[])]);const owner=JSON.parse(sessionStorage.getItem('astra-user-profile')||'{}').email;pending=pending.filter(x=>owner&&x.owner_email===owner);$('#view').innerHTML=`<section class="card form-card"><div class="card-head"><div><h2>Enter a reading</h2><div class="card-sub">Simulated sensor source · blank vital values remain missing.</div></div></div><form id="reading-form"><div class="form-grid"><div class="field"><label>Astronaut</label><select name="astronaut_id" required>${people.map(x=>`<option value="${x.id}">${esc(x.name)} · ${esc(x.call_sign)}</option>`).join('')}</select></div><div class="field"><label>Activity</label><select name="activity">${['RESTING','SLEEPING','WALKING','EXERCISE','WORKING','OTHER'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Environment</label><select name="environment"><option>EARTH</option><option>SPACE</option></select></div><div class="field"><label>Mission phase</label><select name="phase">${['EARTH_PREPARATION','LAUNCH','ORBIT','SPACE_OPERATION','RETURN','POST_MISSION'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Heart rate · BPM</label><input name="heart_rate" type="number" min="20" max="240"></div><div class="field"><label>Oxygen saturation · %</label><input name="spo2" type="number" min="50" max="100"></div><div class="field"><label>Systolic pressure · mmHg</label><input name="systolic" type="number" min="50" max="260"></div><div class="field"><label>Diastolic pressure · mmHg</label><input name="diastolic" type="number" min="30" max="180"></div><div class="field"><label>Sensor quality</label><select name="sensor_quality"><option>VALID</option><option>QUESTIONABLE</option><option>INVALID</option></select></div><div class="field"><label>Sensor source</label><input name="sensor_source" value="SIMULATED"></div></div><div class="form-actions"><button>Save reading</button></div></form></section><div class="toolbar filterbar"><select id="filter-person"><option value="">All astronauts</option>${people.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select><select id="filter-activity"><option value="">All activities</option>${['RESTING','SLEEPING','WALKING','EXERCISE','WORKING','OTHER'].map(x=>`<option>${x}</option>`).join('')}</select><select id="filter-env"><option value="">All environments</option><option>EARTH</option><option>SPACE</option></select><select id="filter-phase"><option value="">All phases</option>${['EARTH_PREPARATION','LAUNCH','ORBIT','SPACE_OPERATION','RETURN','POST_MISSION'].map(x=>`<option>${x}</option>`).join('')}</select><label>From <input id="filter-from" type="date"></label><label>To <input id="filter-to" type="date"></label><button class="secondary" data-action="filter">Apply filters</button></div><div id="reading-table">${card('Health readings',`${xs.length} server records`,table(['Astronaut','Timestamp','Environment','Activity','Heart rate','SpO₂','BP','Quality'],readingRows(xs)))}</div>${pending.length?card('Waiting to synchronize',`${pending.length} record(s) saved on this device. The server has not confirmed them.`,`<div class="notice warn">These items are held in this browser’s IndexedDB queue. They will be sent automatically when this server reconnects and confirms the write.</div>${table(['Queued at','Activity','Environment','Heart rate','SpO₂','Status'],pending.map(x=>`<tr><td>${date(x.queued_at)}</td><td>${esc(x.activity)}</td><td>${esc(x.environment)}</td><td>${x.heart_rate??'—'}</td><td>${x.spo2??'—'}</td><td>${badge('WAITING TO SYNC')}</td></tr>`))}`):''}`}
const actions={setup:async()=>{await api('/demo/setup',{method:'POST'});toast('Demo data ready');await renderPage()},generate:async()=>{let p=await api('/astronauts');if(!p.length)throw Error('Load demo data first.');await api(`/baselines/generate?astronaut_id=${p[0].id}&activity=RESTING`,{method:'POST'});toast('Baseline calculated and queued for review');location.href='/baselines.html'},simulate:async()=>{let x=await api('/demo/simulate-space',{method:'POST'});toast(x.assessment.message);await renderPage()},reset:async()=>{if(!confirm('Remove the synthetic demo astronaut, mission, and their demo records?'))return;await api('/demo/reset',{method:'POST'});toast('Demo data reset');await renderPage()},logout:async()=>{try{await api('/auth/logout',{method:'POST'})}finally{sessionStorage.removeItem('astra-user-profile');await clearLocalCache();location.href='/login.html'}},approve:async e=>{let comments=prompt('Reviewer comment','Baseline reviewed for demonstration.');if(comments===null)return;await api(`/baselines/${e.dataset.id}/review`,{method:'POST',body:JSON.stringify({decision:'APPROVED',comments})});toast('Baseline approved by the signed-in reviewer');await renderPage()},reject:async e=>{let comments=prompt('Reason for rejection','Additional valid readings requested.');if(comments===null)return;await api(`/baselines/${e.dataset.id}/review`,{method:'POST',body:JSON.stringify({decision:'REJECTED',comments})});toast('Baseline rejected with comment');await renderPage()},ack:async e=>{let comments=prompt('Add a review comment','Reviewed; follow-up noted.');if(comments===null)return;await api(`/alerts/${e.dataset.id}/review`,{method:'POST',body:JSON.stringify({status:'ACKNOWLEDGED',comments})});toast('Alert acknowledged');await renderPage()},'edit-astronaut':async e=>{let x=await api(`/astronauts/${e.dataset.id}`),name=prompt('Astronaut name',x.name);if(name===null)return;let call_sign=prompt('Call sign',x.call_sign);if(call_sign===null)return;let role=prompt('Role',x.role);if(role===null)return;let mission=prompt('Mission ID (blank for unassigned)',x.mission_id??'');if(mission===null)return;await api(`/astronauts/${x.id}`,{method:'PUT',body:JSON.stringify({name,call_sign,role,mission_id:mission?Number(mission):null})});toast('Astronaut updated');await renderPage()},'edit-mission':async e=>{let xs=await api('/missions'),x=xs.find(a=>a.id==e.dataset.id);let name=prompt('Mission name',x.name);if(name===null)return;let status=prompt('Status (PLANNED, ACTIVE, COMPLETED)',x.status);if(status===null)return;let phase=prompt('Mission phase',x.phase);if(phase===null)return;let description=prompt('Description',x.description);if(description===null)return;await api(`/missions/${x.id}`,{method:'PUT',body:JSON.stringify({...x,name,status,phase,description})});toast('Mission updated');await renderPage()},filter:async()=>{let q=new URLSearchParams();if($('#filter-activity').value)q.set('activity',$('#filter-activity').value);if($('#filter-env').value)q.set('environment',$('#filter-env').value);let xs=await api('/readings?'+q);$('#reading-table').innerHTML=card('Health readings',`${xs.length} matching records`,table(['Astronaut','Timestamp','Environment','Activity','Heart rate','SpO₂','Quality'],readingRows(xs)))},'report-filter':async()=>{let d=await api('/history'),id=$('#report-person').value;if(id)d=d.filter(r=>r.astronaut_id==id);let a=await api('/alerts'),b=await api('/baselines');if(id){a=a.filter(x=>x.astronaut_id==id);b=b.filter(x=>x.astronaut_id==id)}$('#report-preview').innerHTML=card('ASTRA HEALTH · RESEARCH SUMMARY',`Generated ${new Date().toLocaleString()} · ${d.length} readings`,`<div class="notice">Synthetic information only. Statistical decision support is not clinical diagnosis.</div>${card('Record summary','Selected database records',`<p>${b.length} baseline versions · ${a.length} alerts</p>`)}${table(['Astronaut','Timestamp','Environment','Activity','Heart rate','SpO₂','Quality'],readingRows(d))}`)},'print-report':async()=>window.print()};
function formSetup(){const f=$('#astronaut-form');if(f)f.onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(f));d.mission_id=d.mission_id?Number(d.mission_id):null;await api('/astronauts',{method:'POST',body:JSON.stringify(d)});toast('Astronaut added');await renderPage()};const mform=$('#mission-form');if(mform)mform.onsubmit=async e=>{e.preventDefault();await api('/missions',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(mform)))});toast('Mission created');await renderPage()};const rf=$('#reading-form');if(rf)rf.onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(rf));for(let k of ['astronaut_id','heart_rate','spo2','systolic','diastolic'])d[k]=d[k]===''?null:Number(d[k]);let result=await api('/readings',{method:'POST',body:JSON.stringify(d)});toast(result.local_pending?'Reading saved on this device; waiting to synchronize.':(result.assessment?.message||'Reading synchronized to the local server.'));await renderPage()};const bf=$('#baseline-form');if(bf)bf.onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(bf));await api(`/baselines/generate?astronaut_id=${d.astronaut_id}&activity=${d.activity}`,{method:'POST'});toast('Baseline generated and queued for review');await renderPage()}}
async function renderPage(){let page=document.body.dataset.page;if(page==='login'){try{await loginPage()}catch(e){$('#app').innerHTML=`<section class="login-card"><h2>Sign-in is temporarily unavailable</h2><p>${esc(e.message)}</p><button onclick="location.reload()">Try again</button></section>`}return}shell(page);try{let me;try{me=await api('/auth/me');sessionStorage.setItem('astra-user-profile',JSON.stringify(me))}catch(e){if(!navigator.onLine)me=JSON.parse(sessionStorage.getItem('astra-user-profile')||'null');if(!me)throw e}$('#identity').textContent=`${me.full_name} · ${me.role.replaceAll('_',' ')}`;refreshNoticeCount();const view={dashboard,astronauts,missions,readings,baselines,alerts,history,analytics,medical,reports,settings,notifications}[page];if(!view)throw Error('This section is not available.');await view();formSetup();if(navigator.onLine)syncPending()}catch(e){$('#view').innerHTML=`<section class="card"><strong>We could not load this page.</strong><p>${esc(e.message)}</p><button data-action="retry">Try again</button></section>`}}
document.addEventListener('click',async e=>{let a=e.target.closest('[data-action]');if(!a)return;try{if(a.dataset.action==='retry')return renderPage();await actions[a.dataset.action]?.(a)}catch(err){toast(err.message)}});
actions.filter=async()=>{let q=new URLSearchParams();for(const [input,param] of [['filter-person','astronaut_id'],['filter-activity','activity'],['filter-env','environment'],['filter-phase','phase']])if($(`#${input}`).value)q.set(param,$(`#${input}`).value);if($('#filter-from').value)q.set('from_date',new Date($('#filter-from').value).toISOString());if($('#filter-to').value)q.set('to_date',new Date($('#filter-to').value+'T23:59:59').toISOString());let xs=await api('/readings?'+q);$('#reading-table').innerHTML=card('Health readings',`${xs.length} matching server records`,table(['Astronaut','Timestamp','Environment','Activity','Heart rate','SpO₂','BP','Quality'],readingRows(xs)))};
actions['report-filter']=async()=>{let rows=await api('/history'),id=$('#report-person').value;if(id)rows=rows.filter(r=>r.astronaut_id==id);let bs=await api('/baselines'),als=await api('/alerts');if(id){bs=bs.filter(x=>x.astronaut_id==id);als=als.filter(x=>x.astronaut_id==id)}$('#report-preview').innerHTML=card('ASTRA HEALTH · RESEARCH SUMMARY',`Generated ${new Date().toLocaleString()} · ${rows.length} readings`,`<div class="notice">Synthetic information only. This report is not a clinical assessment.</div><p>${bs.length} baseline versions · ${als.length} alerts</p>${table(['Astronaut','Timestamp','Environment','Activity','Heart rate','SpO₂','Quality'],readingRows(rows))}`)};
if(document.body.dataset.page)renderPage();if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('/service-worker.js').catch(()=>{});

// Chart.js is used when available. The local SVG renderer remains available offline.
function chart(values,color='',labels=[]){const vals=values.filter(x=>x!==null&&x!==undefined).slice(-12);if(vals.length<2)return '<div class="empty"><strong>Not enough readings yet</strong>Load demo data to see this trend.</div>';const uid='astra-chart-'+Math.random().toString(36).slice(2);const safeValues=esc(JSON.stringify(vals));const safeLabels=esc(JSON.stringify(labels.slice(-vals.length)));let min=Math.min(...vals),max=Math.max(...vals),span=max-min||1,pts=vals.map((v,i)=>`${20+i*360/(vals.length-1)},${165-(v-min)/span*125}`).join(' ');const fallback=`<div class="chart-fallback"><svg viewBox="0 0 400 205" preserveAspectRatio="none"><defs><linearGradient id="${uid}-fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#2877ef" stop-opacity=".19"/><stop offset="1" stop-color="#2877ef" stop-opacity="0"/></linearGradient></defs>${[40,80,120,160].map(y=>`<line class="gridline" x1="15" y1="${y}" x2="390" y2="${y}"/>`).join('')}<polygon points="${pts} 380,175 20,175" fill="url(#${uid}-fill)"/><polyline class="line ${color}" points="${pts}"/><text x="18" y="197">Older</text><text x="350" y="197">Recent</text><text x="330" y="25">${esc(Math.round(max))}</text><text x="330" y="169">${esc(Math.round(min))}</text></svg></div>`;if(window.Chart)setTimeout(mountCharts,0);return `<div class="chart" style="position:relative"><canvas id="${uid}" class="chartjs" data-values="${safeValues}" data-labels="${safeLabels}" data-color="${color}" hidden></canvas>${fallback}</div>`}
function mountCharts(){if(!window.Chart)return;document.querySelectorAll('canvas.chartjs:not([data-ready])').forEach(c=>{try{const vals=JSON.parse(c.dataset.values||'[]'),labels=JSON.parse(c.dataset.labels||'[]'),color=c.dataset.color==='cyan'?'#06a6b7':c.dataset.color==='orange'?'#ef9a43':'#2877ef';new Chart(c,{type:'line',data:{labels:labels.length===vals.length?labels:vals.map((_,i)=>`Reading ${i+1}`),datasets:[{data:vals,label:'Saved readings',borderColor:color,backgroundColor:color+'1a',fill:true,tension:.32,pointRadius:2,pointHoverRadius:5,borderWidth:2}]},options:{responsive:true,maintainAspectRatio:false,interaction:{mode:'index',intersect:false},plugins:{legend:{display:false},tooltip:{displayColors:false}},scales:{x:{grid:{display:false},ticks:{maxTicksLimit:5,maxRotation:0}},y:{grid:{color:'#edf1f6'},ticks:{maxTicksLimit:5}}}}});c.hidden=false;c.dataset.ready='true';const f=c.parentElement.querySelector('.chart-fallback');if(f)f.hidden=true}catch(e){console.warn('Chart renderer unavailable; using the local chart fallback.',e)}})}
window.addEventListener('astra-charts-ready',mountCharts);

async function updateNetwork(){const c=$('#connection'),n=$('#network');if(!navigator.onLine){if(c)c.textContent='Offline · cached shell';if(n)n.textContent='Offline · API changes will queue when possible';return}if(c)c.textContent='Checking local server…';if(n)n.textContent='Network available';try{const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),1800);const r=await fetch('/api/health',{signal:controller.signal,credentials:'same-origin'});clearTimeout(timer);if(!r.ok)throw Error('server unavailable');const d=await r.json();if(d.status!=='ok')throw Error('server unavailable');if(c)c.textContent='Local server connected';if(n)n.textContent='Online · API ready'}catch{if(c)c.textContent='Network online · local server unavailable';if(n)n.textContent='Cached data available · live changes wait for server'}}
async function syncPending(){if(!navigator.onLine)return;let records;try{const all=await getQueued(),email=JSON.parse(sessionStorage.getItem('astra-user-profile')||'{}').email;records=all.filter(x=>email&&x.owner_email===email)}catch{return}let completed=0;for(const item of records){try{const r=await fetch('/api/readings',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(item)});if(r.ok){await clearQueued(item.client_request_id);completed++}else if(r.status===401){location.href='/login.html';return}else if(r.status===409){toast('A queued reading needs review before it can be synchronized.');return}}catch{return}}if(completed){toast(`${completed} queued reading(s) synchronized with the server.`);if(document.body.dataset.page==='readings')await renderPage()}}

async function notifications(){const items=await api('/notifications'),unread=items.filter(x=>x.unread);const rows=items.map(n=>`<tr><td><strong>${esc(n.title)}</strong></td><td>${esc(n.message)}</td><td>${date(n.created_at)}</td><td>${badge(n.unread?'UNREAD':'READ')}</td><td>${n.unread?`<button class="secondary small" data-action="mark-notification" data-id="${n.id}">Mark read</button>`:`<a class="text-link" href="${esc(n.href)}">Open →</a>`}</td></tr>`);$('#view').innerHTML=`<div class="toolbar" style="margin-bottom:14px"><span class="offline-note">${unread.length} unread notification(s) for this account.</span>${unread.length?'<button class="secondary" data-action="mark-all-notifications">Mark all as read</button>':''}</div>${card('Your notifications','Role-specific review and mission updates',table(['Update','Details','Received','Status','Action'],rows,'No notifications yet. New review tasks appear here.'))}`}
async function refreshNoticeCount(){const el=$('#notice-count');if(!el)return;try{const xs=await api('/notifications');el.textContent=xs.filter(x=>x.unread).length;el.classList.toggle('has-notices',Number(el.textContent)>0)}catch{el.textContent='–'}}
actions['mark-notification']=async e=>{await api(`/notifications/${e.dataset.id}/read`,{method:'POST'});await renderPage()};
actions['mark-all-notifications']=async()=>{await api('/notifications/read-all',{method:'POST'});toast('Notifications marked as read');await renderPage()};
async function settings(){const me=await api('/auth/me');$('#view').innerHTML=`<div class="grid section-grid"><section class="card"><div class="card-head"><div><h2>Account security</h2><div class="card-sub">Signed in as ${esc(me.full_name)} · ${esc(me.role.replaceAll('_',' '))}</div></div></div><div class="notice">The browser uses a short-lived HttpOnly session cookie. Passwords are stored as salted PBKDF2 hashes.</div><form id="password-form" class="form-grid"><div class="field"><label>Current password</label><input name="current_password" type="password" required autocomplete="current-password"></div><div class="field"><label>New password</label><input name="new_password" type="password" minlength="12" required autocomplete="new-password"></div><div class="form-actions"><button>Change password</button></div></form><div class="notice warn">Prototype roles are local access labels. They do not verify professional credentials.</div></section><section class="card"><div class="card-head"><div><h2>Account management</h2><div class="card-sub">Administrator role required to add or change accounts.</div></div></div><div id="user-list"><div class="spinner"></div></div></section></div><div class="card" style="margin-top:16px"><div class="card-head"><div><h2>Audit activity</h2><div class="card-sub">Recent authentication and review events.</div></div></div><div id="audit-list">Loading access log…</div></div>`;$('#password-form').onsubmit=async e=>{e.preventDefault();await api('/auth/password',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});e.currentTarget.reset();toast('Password updated; other sessions were signed out.')};try{const users=await api('/users');$('#user-list').innerHTML=`<form id="user-form"><div class="form-grid"><div class="field"><label>Full name</label><input name="full_name" required></div><div class="field"><label>Email</label><input name="email" type="email" required></div><div class="field"><label>Role</label><select name="role">${['MEDICAL_OFFICER','RESEARCHER','ASTRONAUT','ADMINISTRATOR'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Initial password (12+ characters)</label><input name="password" type="password" minlength="12" required></div></div><div class="form-actions"><button>Add account</button></div></form>${table(['Name','Email','Role','Status','Action'],users.map(u=>`<tr><td>${esc(u.full_name)}</td><td>${esc(u.email)}</td><td>${badge(u.role)}</td><td>${badge(u.active?'ACTIVE':'INACTIVE')}</td><td>${u.id!==me.id?(u.active?`<button class="secondary small" data-action="manage-user" data-id="${u.id}">Edit / deactivate</button>`:'—'):'Current account'}</td></tr>`))}`;$('#user-form').onsubmit=async e=>{e.preventDefault();await api('/users',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});toast('Account created');await settings()};$('#audit-list').innerHTML=table(['When','User','Action','Record','Details'],(await api('/audit-logs')).map(x=>`<tr><td>${date(x.created_at)}</td><td>${esc(x.user_name)}</td><td>${esc(x.action)}</td><td>${esc(x.entity)} ${esc(x.entity_id||'')}</td><td>${esc(x.detail)}</td></tr>`))}catch(e){$('#user-list').innerHTML=`<div class="notice">${esc(e.message)} Account administration is available to Administrators.</div>`;$('#audit-list').textContent='Audit log access is restricted to Administrators.'}}
actions['manage-user']=async e=>{const users=await api('/users'),u=users.find(x=>x.id==e.dataset.id);if(!u)throw Error('Account not found.');const role=prompt('Set role: ADMINISTRATOR, MEDICAL_OFFICER, RESEARCHER, or ASTRONAUT',u.role);if(role===null)return;const deactivate=confirm('Deactivate this account and revoke its sessions? Choose Cancel to keep it active.');const updated=await api(`/users/${u.id}`,{method:'PUT',body:JSON.stringify({role:role.toUpperCase(),active:deactivate?false:true})});toast(`Account ${updated.active?'updated':'deactivated'}`);await settings()};

async function dashboard(){await dashboardCore();const missions=await api('/missions');$('#view').insertAdjacentHTML('beforeend',card('Mission overview','Current mission phase and crew assignment',table(['Mission','Status','Phase','Crew','Dates'],missions.slice(0,5).map(x=>`<tr><td><strong>${esc(x.name)}</strong></td><td>${badge(x.status)}</td><td>${esc(x.phase)}</td><td>${x.astronaut_count??0}</td><td>${esc(x.start_date||'—')} – ${esc(x.end_date||'ongoing')}</td></tr>`),'No mission records yet. Create a mission to get started.')))}
